import type { Theme } from "../source/theme.ts";
import { shadowCss } from "./css-web.ts";
import { nativeFamilies, nativeFamily, nativeMetrics } from "./native-fonts.ts";

const header =
  "/* Generated by @ome-labs/tokens from tokens/*.json: edit the JSON, then run `pnpm build`. */";

/**
 * The theme for Uniwind (Tailwind 4 on React Native). Uniwind reads theme colours from `@layer theme`
 * with one `@variant` per theme, and every theme must declare the same names. React Native needs
 * absolute line heights and letter spacing, and one font family per weight.
 */
export function nativeCss(theme: Theme): string {
  // Uniwind turns box-shadow into React Native's `boxShadow`, which takes inset and several layers.
  const colors = (mode: "light" | "dark") =>
    [
      ...theme.semantic.map((color) => `      --color-${color.utility}: ${color[mode]};`),
      ...theme.elevation.map(
        (elevation) => `      --shadow-${elevation.name}: ${shadowCss(elevation[mode])};`,
      ),
    ].join("\n");

  const typeUtilities = theme.text.map((style) => {
    const { lineHeight, letterSpacing } = nativeMetrics(style);

    return [
      `@utility type-${style.name} {`,
      `  font-family: ${nativeFamily(style)};`,
      `  font-size: ${style.size}px;`,
      `  line-height: ${lineHeight}px;`,
      `  letter-spacing: ${letterSpacing}px;`,
      ...(style.uppercase ? ["  text-transform: uppercase;"] : []),
      "}",
    ].join("\n");
  });

  // `font-sans` is the regular weight; the other weights are their own families (`font-sans-medium`).
  const weightSuffix: Record<number, string> = {
    400: "",
    500: "-medium",
    600: "-semibold",
    700: "-bold",
  };
  const fonts = Object.entries(nativeFamilies).flatMap(([family, weights]) =>
    Object.entries(weights).map(
      ([weight, file]) => `  --font-${family}${weightSuffix[Number(weight)]}: ${file};`,
    ),
  );

  return [
    header,
    "",
    "@layer theme {",
    "  :root {",
    "    @variant light {",
    colors("light"),
    "    }",
    "    @variant dark {",
    colors("dark"),
    "    }",
    "  }",
    "}",
    "",
    "@theme {",
    ...fonts,
    ...theme.text.map((style) => `  --text-${style.name}: ${style.size}px;`),
    "  --spacing: 4px;",
    ...theme.radius.map((radius) => `  --radius-${radius.name}: ${radius.px}px;`),
    ...theme.control.map((control) => `  --height-control-${control.name}: ${control.px}px;`),
    "}",
    "",
    ...typeUtilities,
    "",
  ].join("\n");
}
